-- Registre phyto au format réglementaire, lot X (retours du 10/11/2026).
-- Arrêté du 24/12/2025 (JORFTEXT000053228465) et notice ministérielle du
-- 22/09/2026 : intitulés standard, culture en code OEPP, stade BBCH, SIRET.
-- Référentiels du ministère (agriculture.gouv.fr/telecharger/156212 et
-- 156203), chargés tels quels ; `match_key` : nom sans accents ni
-- ponctuation, pour proposer la culture d'une activité.

CREATE TABLE ref_phyto_crops (
  code             text PRIMARY KEY,          -- code culture/situation (ex. 55501)
  label            text NOT NULL,             -- dénomination (ex. Maïs)
  match_key        text NOT NULL,
  oepp             text,                      -- code OEPP (ex. ZEAMX)
  non_agricultural boolean NOT NULL DEFAULT false,
  bbch_ref         text                       -- référence BBCH conseillée (ex. Maïs)
);
CREATE INDEX ref_phyto_crops_match ON ref_phyto_crops (match_key);

CREATE TABLE ref_bbch_stages (
  code        text PRIMARY KEY,               -- ex. SP_55501_15
  bbch_ref    text NOT NULL,                  -- ex. Maïs
  label       text NOT NULL,                  -- ex. BBCH 15, Stade 1
  description text
);
CREATE INDEX ref_bbch_stages_ref ON ref_bbch_stages (bbch_ref);

GRANT SELECT ON ref_phyto_crops, ref_bbch_stages TO fourmy_app;

