INSERT INTO ref_bbch_stages (code, bbch_ref, label, description) VALUES
('SP_20501_S0', 'Agrumes', 'Stade 0', 'Développement des bourgeons'),
('SP_20501_00', 'Agrumes', 'BBCH 00', 'dormance : les bourgeons des feuilles et des inflorescences sont indifférenciées, fermés et recouverts d’écailles vertes'),
('SP_20501_01', 'Agrumes', 'BBCH 01', 'début du gonflement des bourgeons'),
('SP_20501_03', 'Agrumes', 'BBCH 03', 'fin du gonflement des bourgeons : les écailles vertes sont légèrement séparées'),
('SP_20501_07', 'Agrumes', 'BBCH 07', 'début de l’éclatement des bourgeons'),
('SP_20501_09', 'Agrumes', 'BBCH 09', 'les primordiums foliaires sont visibles'),
('SP_20501_S1', 'Agrumes', 'Stade 1', 'Développement des feuilles'),
('SP_20501_10', 'Agrumes', 'BBCH 10', 'les premières feuilles se séparent, les écailles vertes s’ouvrent légèrement et les feuilles sortent'),
('SP_20501_11', 'Agrumes', 'BBCH 11', 'les premières feuilles sont visibles'),
('SP_20501_15', 'Agrumes', 'BBCH 15', 'd''autres feuilles sont visibles mais n’ont pas encore atteint leur taille finale'),
('SP_20501_19', 'Agrumes', 'BBCH 19', 'les premières feuilles ont atteint leur taille finale'),
('SP_20501_S3', 'Agrumes', 'Stade 3', 'Développement des pousses'),
('SP_20501_31', 'Agrumes', 'BBCH 31', 'début de la croissance des pousses: l’axe de la pousse devient visible'),
('SP_20501_32', 'Agrumes', 'BBCH 32', 'les pousses ont atteint 20% de leur taille finale'),
('SP_20501_33', 'Agrumes', 'BBCH 33', 'les pousses ont atteint 30% de leur taille finale'),
('SP_20501_34', 'Agrumes', 'BBCH 34', 'les pousses ont atteint 40% de leur taille finale'),
('SP_20501_35', 'Agrumes', 'BBCH 35', 'les pousses ont atteint 50% de leur taille finale'),
('SP_20501_36', 'Agrumes', 'BBCH 36', 'les pousses ont atteint 60% de leur taille finale'),
('SP_20501_37', 'Agrumes', 'BBCH 37', 'les pousses ont atteint 70% de leur taille finale'),
('SP_20501_38', 'Agrumes', 'BBCH 38', 'les pousses ont atteint 80% de leur taille finale'),
('SP_20501_39', 'Agrumes', 'BBCH 39', 'les pousses ont atteint 90% de leur taille finale'),
('SP_20501_S5', 'Agrumes', 'Stade 5', 'Développement de l’inflorescence'),
('SP_20501_51', 'Agrumes', 'BBCH 51', 'gonflement des bourgeons de l''inflorescence : les bourgeons sont fermés, des écailles vert clair apparaissent'),
('SP_20501_53', 'Agrumes', 'BBCH 53', 'éclatement des bourgeons : les écailles s''écartent et laissent apparaître certaine parties du bourgeon'),
('SP_20501_55', 'Agrumes', 'BBCH 55', 'les fleurs sont visibles, mais encore fermées (boutons verts), elles sont distribuées d''une façon isolée ou en racème, dans des inflorescences avec ou sans feuilles'),
('SP_20501_56', 'Agrumes', 'BBCH 56', 'les pétales s''allongent, les sépales entourent la moitié de la corolle (stade bouton blanc)'),
('SP_20501_57', 'Agrumes', 'BBCH 57', 'les sépales sont ouverts : la pointe de spétales, toujours fermés, est visible. Les feluers ont des pétales blancs ou pourpres'),
('SP_20501_59', 'Agrumes', 'BBCH 59', 'la plupart des fleurs forment avec leurs pétales un ballon creux et allongé'),
('SP_20501_S6', 'Agrumes', 'Stade 6', 'Floraison'),
('SP_20501_60', 'Agrumes', 'BBCH 60', 'les premières fleurs sont ouvertes'),
('SP_20501_61', 'Agrumes', 'BBCH 61', 'début de la floraison : environ 10% des fleurs sont ouvertes'),
('SP_20501_65', 'Agrumes', 'BBCH 65', 'pleine floraison : au minimum 50% des fleurs sont ouvertes, les premiers pétales sont tombés'),
('SP_20501_67', 'Agrumes', 'BBCH 67', 'les fleurs sont flétries : la majorité des pétales sont tombés'),
('SP_20501_69', 'Agrumes', 'BBCH 69', 'fin de la floraison: tous les pétales sont tombés'),
('SP_20501_S7', 'Agrumes', 'Stade 7', 'Développement du fruit'),
('SP_20501_71', 'Agrumes', 'BBCH 71', 'nouaison du fruit : début du grossissement de l''ovaire. Début de la chute de jeunes fruits'),
('SP_20501_72', 'Agrumes', 'BBCH 72', 'Le fruit vert est entouré par les sépales en forme d''une couronne'),
('SP_20501_73', 'Agrumes', 'BBCH 73', 'Quelques fruits jaunissent : début de la chute physiologique des fruits'),
('SP_20501_74', 'Agrumes', 'BBCH 74', 'le fruit de couleur vert foncé a atteint environ 40% de sa taille finale : fin de la chute'),
