-- Détenteur du registre : SIRET (14 chiffres) et numéro PACAGE (9 chiffres).
ALTER TABLE farms ADD COLUMN siret text CHECK (siret ~ '^[0-9]{14}$');
ALTER TABLE farms ADD COLUMN pacage text CHECK (pacage ~ '^[0-9]{9}$');

-- Culture réglementaire d'une activité (code du référentiel) ; sans choix,
-- proposée d'après le libellé Lexicon ou le nom de l'activité.
ALTER TABLE activities ADD COLUMN crop_code text REFERENCES ref_phyto_crops(code);

-- Stade BBCH d'un traitement (facultatif, « le cas échéant »).
ALTER TABLE interventions ADD COLUMN bbch text REFERENCES ref_bbch_stages(code);

-- Nom normalisé (même règle que match_key).
CREATE FUNCTION fourmy_match_key(t text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT btrim(regexp_replace(regexp_replace(lower(translate(coalesce(t, ''),
    'ÀÂÄÁÃÉÈÊËÍÌÎÏÓÒÔÖÕÚÙÛÜÇÑàâäáãéèêëíìîïóòôöõúùûüçñœŒ',
    'AAAAAEEEEIIIIOOOOOUUUUCNaaaaaeeeeiiiiooooouuuucnoO')), '[’''`-]', ' ', 'g'), '\s+', ' ', 'g'))
$$;

-- Culture proposée : la dénomination la plus longue qui commence le libellé
-- (« Maïs grain » → Maïs, « Maïs doux » → Maïs doux).
CREATE FUNCTION fourmy_propose_crop(p_label text) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT c.code FROM ref_phyto_crops c
  WHERE fourmy_match_key(p_label) = c.match_key OR fourmy_match_key(p_label) LIKE c.match_key || ' %'
  ORDER BY length(c.match_key) DESC, c.code LIMIT 1
$$;

-- Culture d'une activité : choisie, sinon proposée (Lexicon, puis nom).
CREATE FUNCTION fourmy_activity_crop(p_activity uuid) RETURNS text
LANGUAGE sql STABLE SECURITY INVOKER AS $$
  SELECT coalesce(a.crop_code, fourmy_propose_crop(lp.label), fourmy_propose_crop(a.name))
  FROM activities a LEFT JOIN lexicon_productions lp ON lp.reference_name = a.reference
  WHERE a.id = p_activity
$$;

GRANT EXECUTE ON FUNCTION fourmy_match_key(text), fourmy_propose_crop(text), fourmy_activity_crop(uuid) TO fourmy_app;
